1: // Copyright lowRISC contributors (OpenTitan project).
2: // Licensed under the Apache License, Version 2.0, see LICENSE for details.
3: // SPDX-License-Identifier: Apache-2.0
4: 
5: // DMI gate for the RISC-V Debug Module
6: //
7: // This module latches the power-on strap for DM enablement from lc_ctrl and
8: // gates the DMI if debugging is not enabled. It also monitors for lc_ctrl
9: // events that would invalidate the strap.
10: 
11: `include "prim_assert.sv"
12: 
13: module rv_dm_dmi_gate
14:   import lc_ctrl_pkg::*;
15: #(
16:   parameter bit SecVolatileRawUnlockEn = 0
17: ) (
18:   input                            clk_i,
19:   input                            rst_ni,
20:   // ---------- VOLATILE_TEST_UNLOCKED CODE SECTION START ----------
21:   // NOTE THAT THIS IS A FEATURE FOR TEST CHIPS ONLY TO MITIGATE
22:   // THE RISK OF A BROKEN OTP MACRO. THIS WILL BE DISABLED VIA
23:   // SecVolatileRawUnlockEn AT COMPILETIME FOR PRODUCTION DEVICES.
24:   // ---------------------------------------------------------------
25:   // Strap sampling override that is only used when SecVolatileRawUnlockEn = 1, Otherwise this input
26:   // is unused. This needs to be synchronized since it is coming from a different clock domain.
27:   // This signal goes from 0 -> 1 and then stays high, since we only ever re-sample once. The
28:   // synchronization logic can therefore just detect the edge to create the sampling pulse
29:   // internally.
30:   input                            strap_en_override_i,
31:   // ----------- VOLATILE_TEST_UNLOCKED CODE SECTION END -----------
32:   input                            strap_en_i,
33:   // LC signals for DMI qualification
34:   input  lc_ctrl_pkg::lc_tx_t      lc_hw_debug_en_i,
35:   input  lc_ctrl_pkg::lc_tx_t      lc_check_byp_en_i,
36:   input  lc_ctrl_pkg::lc_tx_t      lc_escalate_en_i,
37: 
38:   // TL-UL-based DMI
39:   input  tlul_pkg::tl_h2d_t        dbg_tl_h2d_win_i,
40:   output tlul_pkg::tl_d2h_t        dbg_tl_d2h_win_o,
41: 
42:   // Gated Rocket Legacy DMI
43:   output                           dmi_req_valid_o,
44:   input                            dmi_req_ready_i,
45:   output dm::dmi_req_t             dmi_req_o,
46:   input                            dmi_rsp_valid_i,
47:   output                           dmi_rsp_ready_o,
48:   input  dm::dmi_resp_t            dmi_rsp_i,
49: 
50:   // Integrity error
51:   output                           intg_error_o
52: );
53:   /////////////////////////////////////
54:   // Life cycle signal synchronizers //
55:   /////////////////////////////////////
56: 
57:   lc_tx_t [0:0] lc_hw_debug_en;
58:   prim_lc_sync #(
59:     .NumCopies(1)
60:   ) u_prim_lc_sync_lc_hw_debug_en (
61:     .clk_i,
62:     .rst_ni,
63:     .lc_en_i(lc_hw_debug_en_i),
64:     .lc_en_o(lc_hw_debug_en)
65:   );
66:   lc_tx_t [0:0] lc_check_byp_en;
67:   prim_lc_sync #(
68:     .NumCopies(1)
69:   ) u_prim_lc_sync_lc_check_byp_en (
70:     .clk_i,
71:     .rst_ni,
72:     .lc_en_i(lc_check_byp_en_i),
73:     .lc_en_o(lc_check_byp_en)
74:   );
75:   lc_tx_t [0:0] lc_escalate_en;
76:   prim_lc_sync #(
77:     .NumCopies(1)
78:   ) u_prim_lc_sync_lc_escalate_en (
79:     .clk_i,
80:     .rst_ni,
81:     .lc_en_i(lc_escalate_en_i),
82:     .lc_en_o(lc_escalate_en)
83:   );
84: 
85:   //////////////////////////
86:   // Strap Sampling Logic //
87:   //////////////////////////
88: 
89:   logic strap_en;
90:   if (SecVolatileRawUnlockEn) begin : gen_strap_override
91:     logic strap_en_override_d, strap_en_override_q;
92: 
93:     prim_flop_2sync #(
94:       .Width(1),
95:       .ResetValue(0)
96:     ) u_prim_flop_2sync (
97:       .clk_i,
98:       .rst_ni,
99:       .d_i(strap_en_override_i),
100:       .q_o(strap_en_override_d)
101:     );
102: 
103:     always_ff @(posedge clk_i or negedge rst_ni) begin : p_strap_override_reg
104:       if(!rst_ni) begin
105:         strap_en_override_q <= 1'b0;
106:       end else begin
107:         strap_en_override_q <= strap_en_override_d;
108:       end
109:     end
110: 
111:     // Detect a posedge on the override signal and reflect it for just a cycle on strap_en
112:     // (ignoring the fact that strap_en_override_i will stay high afterwards).
113:     assign strap_en = strap_en_i || (strap_en_override_d && !strap_en_override_q);
114: 
115:     // Once strap_en_override_i is asserted, it will always stay high
116:     `ASSUME(LcCtrlStrapSampleOverrideOnce_A, strap_en_override_i |=> strap_en_override_i)
117: 
118:   end else begin : gen_no_strap_override
119:     logic unused_strap_en_override;
120:     assign unused_strap_en_override = strap_en_override_i;
121:     assign strap_en                 = strap_en_i;
122:   end
123: 
124:   /////////////////////////////
125:   // LC_HW_DEBUG_EN Latching //
126:   /////////////////////////////
127: 
128:   // In order to keep a RV_DM JTAG debug session alive during NDM reset, we need to memorize the
129:   // state of lc_hw_debug_en, since OTP/LC will be reset as part of NDM reset (the only parts not
130:   // reset are in the pwr/rst/clkmgrs, RV_DM and this strap sampling module). We sample the life
131:   // cycle signal state when the strap sampling pulse is asserted but the PWRMGR. This pulse is
132:   // asserted once during boot (and not after an NDM reset).
133:   //
134:   // Note that we make sure to invalidate the sampled lc_hw_debug_en whenever lc_check_byp_en or
135:   // lc_escalate_en are not OFF. lc_escalate_en is asserted as part of an escalation, and
136:   // lc_check_byp_en is asserted whenever a life cycle transition is initiated (it causes the OTP
137:   // controller to skip background checks on the life cycle partition as it undergoes
138:   // modification). This makes sure that the sampled value here does not survive a life cycle
139:   // transition.
140:   //
141:   // Finally, note that there is secondary gating on the RV_DM and DFT TAPs that is always consuming
142:   // live lc_hw_debug_en and lc_dft_en signals for added protection.
143: 
144:   // Convert the strap enable pulse to a mubi signal and mask lc_hw_debug_en with it.
145:   lc_tx_t lc_strap_en, lc_hw_debug_en_masked;
146:   assign lc_strap_en = lc_tx_bool_to_lc_tx(strap_en);
147:   assign lc_hw_debug_en_masked = lc_tx_and_hi(lc_strap_en, lc_hw_debug_en[0]);
148: 
149:   // Output ON if
150:   // - If the strap sampling pulse is asserted and lc_hw_debug_en is ON
151:   // - If the strap_hw_debug_en_q is already set to ON (this is the latching feedback loop)
152:   // Note: make sure we use a hardened, rectifying OR function since otherwise two non-strict
153:   // values may produce a strict ON value.
154:   lc_tx_t hw_debug_en_set, strap_hw_debug_en_q;
155:   prim_lc_or_hardened #(
156:     .ActVal(On)
157:   ) u_prim_lc_or_hardened (
158:     .clk_i,
159:     .rst_ni,
160:     .lc_en_a_i(lc_hw_debug_en_masked),
161:     .lc_en_b_i(strap_hw_debug_en_q),
162:     .lc_en_o  (hw_debug_en_set)
163:   );
164: 
165:   // Output ON if either lc_check_byp_en or lc_escalate_en is set to OFF.
166:   lc_tx_t hw_debug_en_gating;
167:   assign hw_debug_en_gating = lc_tx_inv(lc_tx_and_lo(lc_check_byp_en[0], lc_escalate_en[0]));
168: 
169:   // Gate the hw_debug_en_set signal and feed it into the latching flop.
170:   lc_tx_t strap_hw_debug_en_d;
171:   assign strap_hw_debug_en_d = lc_tx_and_hi(hw_debug_en_set, hw_debug_en_gating);
172: 
173:   prim_lc_sender u_prim_lc_sender_strap_hw_debug_en (
174:     .clk_i,
175:     .rst_ni,
176:     .lc_en_i(strap_hw_debug_en_d),
177:     .lc_en_o(strap_hw_debug_en_q)
178:   );
179: 
180:   typedef enum logic [1:0] {
181:     StEnDmiTlulAdapter,
182:     StEnDmiTlulLcGate,
183:     StEnDmiTlulLast
184:   } strap_hw_debug_en_e;
185: 
186:   lc_tx_t [StEnDmiTlulLast-1:0] strap_hw_debug_en;
187:   prim_lc_sync #(
188:     .NumCopies(int'(StEnDmiTlulLast)),
189:     .AsyncOn(0) // no sync needed
190:   ) u_prim_lc_sync_strap_hw_debug_en (
191:     .clk_i,
192:     .rst_ni,
193:     .lc_en_i(strap_hw_debug_en_q),
194:     .lc_en_o(strap_hw_debug_en)
195:   );
196: 
197:   // SEC_CM: DM_EN.CTRL.LC_GATED
198:   logic dmi_en;
199:   assign dmi_en = lc_tx_test_true_strict(strap_hw_debug_en[StEnDmiTlulAdapter]);
200: 
201:   ////////////////////////////////
202:   // TL-UL to Rocket Legacy DMI //
203:   ////////////////////////////////
204: 
205:   logic dbg_gate_intg_error, dmi_intg_error;
206:   assign intg_error_o = dbg_gate_intg_error | dmi_intg_error;
207: 
208:   tlul_pkg::tl_h2d_t dbg_tl_h2d_gated;
209:   tlul_pkg::tl_d2h_t dbg_tl_d2h_gated;
210:   tlul_lc_gate #(
211:     // If the DMI side is gated, the spec requires the DM to return a valid all-zero response.
212:     .ReturnBlankResp(1)
213:   ) u_tlul_lc_gate_dbg (
214:     .clk_i,
215:     .rst_ni,
216:     .tl_h2d_i      (dbg_tl_h2d_win_i),
217:     .tl_d2h_o      (dbg_tl_d2h_win_o),
218:     .tl_h2d_o      (dbg_tl_h2d_gated),
219:     .tl_d2h_i      (dbg_tl_d2h_gated),
220:     // The DMI side should not be flushed upon NDM-reset since we keep the
221:     // debugger side of the connection stable during an NDM-reset request.
222:     .flush_req_i   (1'b0),
223:     .flush_ack_o   (),
224:     .resp_pending_o(),
225:     .lc_en_i       (strap_hw_debug_en[StEnDmiTlulLcGate]),
226:     .err_o         (dbg_gate_intg_error)
227:   );
228: 
229:   logic dmi_req_ready, dmi_rsp_valid;
230:   tlul_adapter_dmi u_tlul_adapter_dmi (
231:     .clk_i,
232:     .rst_ni,
233:     .tl_h2d_i        (dbg_tl_h2d_gated),
234:     .tl_d2h_o        (dbg_tl_d2h_gated),
235:     .intg_error_o    (dmi_intg_error),
236:     .dmi_req_valid_o (dmi_req_valid_o),
237:     .dmi_req_ready_i (dmi_req_ready),
238:     .dmi_req_o       (dmi_req_o),
239:     .dmi_resp_valid_i(dmi_rsp_valid),
240:     .dmi_resp_ready_o(dmi_rsp_ready_o),
241:     .dmi_resp_i      (dmi_rsp_i)
242:   );
243: 
244:   assign dmi_req_ready = dmi_req_ready_i & dmi_en;
245:   assign dmi_rsp_valid = dmi_rsp_valid_i & dmi_en;
246: 
247:   ////////////////
248:   // Assertions //
249:   ////////////////
250: 
251:   // Check that we can correctly latch upon strap_en_i
252:   `ASSERT(LcHwDebugEnSet_A,
253:       (lc_tx_test_true_strict(lc_hw_debug_en[0]) ||
254:        lc_tx_test_true_strict(strap_hw_debug_en_q)) &&
255:       lc_tx_test_false_strict(lc_check_byp_en[0]) &&
256:       lc_tx_test_false_strict(lc_escalate_en[0]) &&
257:       strap_en_i
258:       |=>
259:       lc_tx_test_true_strict(strap_hw_debug_en_q))
260:   // Check that latching ON can only occur if lc_hw_debug_en_i is set.
261:   `ASSERT(LcHwDebugEnSetRev0_A,
262:       lc_tx_test_false_loose(strap_hw_debug_en_q) ##1
263:       lc_tx_test_true_strict(strap_hw_debug_en_q)
264:       |->
265:       $past(lc_tx_test_true_strict(lc_hw_debug_en[0])))
266:   // Check that latching ON can only occur if strap_en is set.
267:   `ASSERT(LcHwDebugEnSetRev1_A,
268:       lc_tx_test_false_loose(strap_hw_debug_en_q) ##1
269:       lc_tx_test_true_strict(strap_hw_debug_en_q)
270:       |->
271:       $past(strap_en))
272:   // Check that any non-OFF value on lc_check_byp_en_i and
