73:   logic [IrLength-1:0]  jtag_ir_shift_d, jtag_ir_shift_q;
74:   // IR register -> this gets captured from shift register upon update_ir
75:   ir_reg_e              jtag_ir_d, jtag_ir_q;
76:   logic capture_ir, shift_ir, update_ir, test_logic_reset; // pause_ir
