91: 
92:     // update IR register
93:     if (update_ir) begin
94:       jtag_ir_d = ir_reg_e'(jtag_ir_shift_q);
95:     end
96: 
97:     if (test_logic_reset) begin
98:       // Bring all TAP state to the initial value.
99:       jtag_ir_shift_d = '0;
100:       jtag_ir_d = IDCODE;
101:     end
102:   end
103: 
