214: 
215:     test_logic_reset   = 1'b0;
216: 
217:     capture_dr         = 1'b0;
218:     shift_dr           = 1'b0;
219:     update_dr          = 1'b0;
220: 
221:     capture_ir         = 1'b0;
222:     shift_ir           = 1'b0;
223:     // pause_ir           = 1'b0; unused
224:     update_ir          = 1'b0;
