314:   // In case of a single TAP those are just feed-through.
315:   assign tck_o = tck_i;
316:   assign tdi_o = td_i;
317:   assign update_o = update_dr;
318:   assign shift_o = shift_dr;
319:   assign capture_o = capture_dr;
320:   assign dmi_clear_o = test_logic_reset;
